// Missing SEO fields are a permanent cost on an owned property, unlike a social post that
// scrolls away. Block rather than warn.
const c = $json.payload.content || {};
const missing = ['title', 'body'].filter(f => !c[f]);
if (!c.meta_description) missing.push('meta_description');
if (!c.slug) missing.push('slug');
if (!(c.asset_urls || []).length) missing.push('hero_image');
if (missing.length) throw new Error('VALIDATION_FAILED: missing required fields for an owned-property publish: ' + missing.join(', '));
const slug = String(c.slug).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
return [{ json: { ...c, slug, canonical: `${$env.CMS_BASE_URL}/${slug}`, structured_data: { '@context': 'https://schema.org', '@type': 'Article', headline: c.title, description: c.meta_description, image: (c.asset_urls || [])[0], datePublished: new Date().toISOString() } } }];
